const message = $input.first().json.message;
const text = message.text || '';
const userId = message.from.id;
const userName = `${message.from.first_name} ${message.from.last_name || ''}`.trim();

// Enhanced input detection
const inputType = {
  isCommand: text.startsWith('/'),
  isPhoto: message.photo !== undefined,
  isVoice: message.voice !== undefined,
  isText: text && !text.startsWith('/'),
};

// Command parsing
let command = null;
if (inputType.isCommand) {
  command = text.split(' ')[0].toLowerCase();
}

// User context setup
const userContext = {
  id: userId,
  name: userName,
  username: message.from.username || '',
  chatId: message.chat.id,
  timestamp: new Date().toISOString()
};

return {
  json: {
    ...userContext,
    inputType,
    command,
    originalMessage: message,
    processingId: `proc_${userId}_${Date.now()}`
  }
};

const command = $input.item.json.command;
const userId = $input.item.json.id;
const chatId = $input.item.json.chatId;

// Enhanced command handling
switch(command) {
  case '/start':
    return {
      json: {
        chatId,
        response: '🇳🇴 Welcome to Enhanced Norsk Cards Bot!\n\n📸 Send a photo - I\'ll identify objects\n📝 Send Ukrainian text - I\'ll translate to Norwegian\n🎤 Send voice message - I\'ll process speech\n📚 Use commands:\n/stats - Your learning progress\n/review - Practice words\n/help - Full instructions\n/settings - Preferences',
        action: 'send_message'
      }
    };

  case '/help':
    return {
      json: {
        chatId,
        response: '🔧 Enhanced Features:\n\n📸 Photo Recognition\n📝 Text Translation (Ukrainian→Norwegian)\n🎤 Voice Processing\n📊 Progress Tracking\n🔄 Batch Processing\n📋 IPA Transcription\n💾 Auto-save to Google Sheets\n\n🎯 Commands:\n/stats - Learning statistics\n/review - Practice session\n/settings - User preferences',
        action: 'send_message'
      }
    };

  case '/stats':
    return {
      json: {
        chatId,
        userId,
        action: 'get_stats'
      }
    };

  case '/review':
    return {
      json: {
        chatId,
        userId,
        action: 'get_review'
      }
    };

  case '/settings':
    return {
      json: {
        chatId,
        response: '⚙️ Settings:\n\n🔊 Audio enabled: Yes\n📝 IPA transcription: Yes\n🎯 Difficulty level: Intermediate\n📊 Progress tracking: Enabled\n\nUse inline buttons to modify settings.',
        action: 'send_message'
      }
