  default:
    return {
      json: {
        chatId,
        response: '❓ Unknown command. Use /help for available commands.',
        action: 'send_message'
      }
    };
}

const item = JSON.parse(JSON.stringify($input.item));

// Check if we have binary data
if (item.binary && item.binary.data) {
  // Fix the MIME type
  item.binary.data.mimeType = 'image/jpeg';

  // If the file has a .jpg or .jpeg extension
  if (item.binary.data.fileName.endsWith('.jpg') || item.binary.data.fileName.endsWith('.jpeg')) {
    item.binary.data.mimeType = 'image/jpeg';
  }
  // If the file has a .png extension
  else if (item.binary.data.fileName.endsWith('.png')) {
    item.binary.data.mimeType = 'image/png';
  }
}

return {json: item.json, binary: item.binary};

